import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"36、【明夷】 离下坤上","description":"周易尚氏学 - 36、【明夷】 离下坤上","frontmatter":{"title":"36、【明夷】 离下坤上","description":"周易尚氏学 - 36、【明夷】 离下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/041.md","filePath":"zh/classics/shangshi/041.md"}'),s={name:"zh/classics/shangshi/041.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_36、【明夷】-离下坤上" tabindex="-1">36、【明夷】 离下坤上 <a class="header-anchor" href="#_36、【明夷】-离下坤上" aria-label="Permalink to “36、【明夷】 离下坤上”">​</a></h1><p>郑云。夷伤也。日出地上。其明乃光。至其人地。明则伤矣。按二至四互坎。故曰艰。坤安故曰贞。利艰贞者。言当明夷之世。宜以艰苦贞定自守也。</p><p>彖曰。明入地中。明夷。内文明而外柔顺。以蒙大难。文王以之。利艰贞。晦其明也。内难而能正其志。箕子以之。</p><p>离文明。坤柔顺。离内坤外。故曰内文明而外柔顺。坎为难。故曰以蒙大难。坤为文。震为王。故曰文王。文王国羌里。几经艰难。而后出之。故日以蒙大难。坤为黑。坎为隐伏。明伏地下。故曰晦其明。坎在下。故曰内难。坎为志为正。故曰内难而能正其志。震为子为箕。故曰箕子。易林贲之屯云。章甫荐履。箕子佯狂。以屯震为箕子也。箕子纣请父。故曰内难。纣囚箕子。箕子佯狂为奴。晦明不用。仅以身免。故曰箕子以之。以用也。易凡于人名地名。无不从象生。除焦延寿外。无知此者。震箕象形。易林屡用。</p><p>象曰。明入地中。明夷。君子以莅众。用晦而明。</p><p>坤为众。震为君子。莅众谓三也。用晦而明。言君子处明夷之世。仍自昭明德也。</p><p>初九。明夷于飞。垂其翼。君子于行。三日不食。有攸往。主人有言。</p><p>此与师六五义同也。辞在五而象全在应。初应在四。四体震。震为飞为翼。坤为下。故曰垂其翼。震为君子。为行。数三。离日故曰三日。震为口为食。坤闭。故三日不食。震为往。为主人。为言。故曰有攸往主人有言。盖初虽应四。而为三所阻格。故飞则不能高。行则不得食。凡有所往。而为主人所恶。责让不安。左传僖十五年。晋筮遇归妹之睽曰。西邻责言。以归妹上震为责言也。震言外向。与我相背。故曰贲言。兹曰有言。与责言义同也。易林同人之坎云。喜其羽翼。飞上乔木。以坎中爻震为鼓为飞。为羽翼。又易林蒙之艮云。。攫饭把肉。以就口食。以艮中爻震为口为食也。易颐象曰。自求口实。以颐下震为口食也。乃震飞震翼震口之象皆失传。旧解皆以属之离。离在地下。且为初爻。胡能飞哉。若食象益茫然不知所指。</p><h3 id="象曰。君子于行。义不食也。" tabindex="-1">象曰。君子于行。义不食也。 <a class="header-anchor" href="#象曰。君子于行。义不食也。" aria-label="Permalink to “象曰。君子于行。义不食也。”">​</a></h3><p>初潜龙勿用。况当明夷之世。方自晦之不暇。当然不得禄食也。</p><p>六二。明夷于左股。用拯马壮吉。</p><p>释文云。股。马王肃作般。孙堂云。般盘之省。汉碑盘字常作股。股常作般。然则马王虽作般。义仍作股。汉时般股通用不分也。互震为左。巽为股。巽伏不见。故曰夷于左股。三震为马。拯。郑云承也。子夏传作升。仍音承。用拯马壮吉者。言二承三。三阳。故壮吉也。旧解独惠栋谓马谓三。而谓三升二故壮。则又非。承者顺。谓阴顺阳。象释曰顺。即释拯义也。</p><h3 id="象曰。六二之吉。顺以则也。" tabindex="-1">象曰。六二之吉。顺以则也。 <a class="header-anchor" href="#象曰。六二之吉。顺以则也。" aria-label="Permalink to “象曰。六二之吉。顺以则也。”">​</a></h3><p>则者法也。阴以阳为则。顺以则。谓阴顺阳。释拯马之义也。乃旧解皆不知其所谓。故愈说愈晦。岂知象以解经。顺即谓拯也。</p><p>九三。明夷于南。句狩。句得其大首。不可疾贞。</p><p>三遇坤。坤为夜为黑。震为南。左传成十六年。晋筮遇复曰。南国戚（左足）。 以坤为国。震为南也。三南遇坤。故曰明夷于南。震为狩为大。坎为首为获。故曰得其大首。言得其渠率也。诗大雅吴天疾威。传。疾犹急也。不可疾。言虽得其大首。不可持之过急也。贞谓宜安定也。疾与贞相对为义。旧读疾贞连文。九家谓不可疾正。最为害理。独项氏玩辞。以贞自为句。与经义合。又旧读以南狩连文。义亦不协。</p><h3 id="象曰。南狩之志。乃大得也。" tabindex="-1">象曰。南狩之志。乃大得也。 <a class="header-anchor" href="#象曰。南狩之志。乃大得也。" aria-label="Permalink to “象曰。南狩之志。乃大得也。”">​</a></h3><p>阳遇阴故大有得。</p><p>六四。入于左腹。获明夷之心。于出门庭。</p><p>震为左。坤为腹。为门庭。为心。四坤体。故曰人于左腹。坤阁故曰获明珍之心于出门庭。震为出。言行至四人坤。悉明夷之故。正在于是也。四当位有应。故无吉凶。坤心之象。益九五云。有孚惠心。心调二。二坤体也。又益九五象云。大得志。志亦谓坤。故易林需之否云。志如死灰。以坤为死为志。人第知坎为心志。不知坤亦为心志。故易辞多误解。</p><h3 id="象曰。入于左腹。获心意也。" tabindex="-1">象曰。入于左腹。获心意也。 <a class="header-anchor" href="#象曰。入于左腹。获心意也。" aria-label="Permalink to “象曰。入于左腹。获心意也。”">​</a></h3><p>坤为心意。故曰获心意。旧解多以三升五成坎为心意。穿凿无理。不可从。</p><p>六五。箕子之明夷。利贞。</p><p>震为箕子已见前。据易林。此箕子则孩子也。夬之中孚云。道路不通。孩子心馈。以中孚互震为孩子。又家人之龚云。孩子贪饵。以伏震为孩子。又损之大畜云。婴儿孩子。未有知识。以大畜上艮为婴儿。互震为孩子。凡易林取象。无不本之易。易他处无孩子象也。宋吴械韵补云。古亥字音喜亦音其。按亥字既读为其。则其字亦必读为亥。淮南子时则训。a （？）萁隧火。高诱注。萁读为该备之该。即a（？） 该燧火也。真既读为该。于是亥孩刻亥（上草）。与其箕常通用。书微子。我旧云刻子。论衡作我旧云孩子。孩子谓纣。言久知其愚蒙昏馈（左　）也。是应为孩子。而作刻子。墨子非攻篇。纣播弃黎老。贼诛孩子。是孩子即箕子。古之所谓诛。不尽是杀。贼诛孩子。即幽囚箕子也。是应为箕子。而作孩子。故此处六五之箕子。汉赵宾又作亥（上草）兹。夫墨子以孩子作箕子。则明夷六五之箕子。易林作孩子。正与墨子合。与论衡同。孩子皆谓纣也。孩箕刻亥（上草）。皆非讹字。以音同古通用。犹盘桓之盘。或作盘。作盘（下木）。作般。皆非讹字也。易林云。婴儿孩子。未有知识。释孩子之义也。六五天子位。孩子之明夷。谓纣昏蒙。惟其指纣。故象传推及于文王箕子。不然。象传之箕子。胡以无一异读哉。故易林姤之明夷云。西戎为疾。幽君去室。明夷六五君位。坤黑。故曰幽君。坎为室。六五在坎外。故曰幽君去室。幽君即释孩子之义。又困之明夷。邃态作云。蒙覆大臣。坤为云。亦释昏蒙之义。又京房易传明夷云。君暗臣明。不可止。君暗谓六五。臣明谓六二。亦以五为君。不以为纣臣。又象传曰。孩子之贞。明不可息也。贞正也。言孩子居天子之正位。天子一日万几。故明不可息。若箕子已晦其明矣。有何不可息。古今释者千百家。于此语未有能通者。盖文王与微子。不欲明斥纣。故以孩子为代名。犹麦秀歌之谓狡童也。观墨子以箕子为孩子。则此之箕子。亦为孩子。易林之读。独得其真。自孩箕音同通用之义弗明。竟作纣臣矣。岂知孩子即谓纣。与微子之孩子同。彼夫赵宾作亥（上草）兹。刘向荀爽作亥（上草）滋。蜀才作其子。王弼作其兹。惠栋作亥子。虽与象传义不合。然皆知作纣臣之必非。乃孔疏不从王注。而从马融。竟作纣臣解。疏已。五本君位。马融作纣臣解。亦知其不安。而以箕子演畴。有君德为解。益可证易林以孩子为纣之精。五承乘皆阴。下又无应。故曰利贞。谓宜艰贞自守不妄动也。</p><h3 id="象曰。箕子之贞。明不可息也。" tabindex="-1">象曰。箕子之贞。明不可息也。 <a class="header-anchor" href="#象曰。箕子之贞。明不可息也。" aria-label="Permalink to “象曰。箕子之贞。明不可息也。”">​</a></h3><p>五为天子。天子一日万几。明息则政乱矣。故曰明不可息。</p><p>上六。不明晦。初登于天。后入于地。</p><p>明夷之初为晋。晋日在地上而为昼。故曰初登于天。乃晋覆成明夷。日在地下而为夜。故曰后人于地。人地故晦而不明。卦正如彼。覆则如此。此文王示序卦之义也。</p><h3 id="象曰。初登于天。照四国也。后入于地。失则也。" tabindex="-1">象曰。初登于天。照四国也。后入于地。失则也。 <a class="header-anchor" href="#象曰。初登于天。照四国也。后入于地。失则也。" aria-label="Permalink to “象曰。初登于天。照四国也。后入于地。失则也。”">​</a></h3><p>坤为国。震卦数四。故曰四国。则谓三。上为四五所格。不能应三。故曰失则。此则字与六二顺以则。谦六四不违则义同。皆谓阳。旧解皆不知失则之故何在。泛说之。非。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
